_COMPARISON_OPS = {"=", "!=", "<", "<=", ">", ">="}


def _collect_operand(opd, specs):
    if isinstance(opd, list) and opd and opd[0] == "agg":
        specs.add((opd[1], opd[2]))


def _collect_aggs(cond, specs):
    if not isinstance(cond, list) or not cond:
        return

    op = cond[0]

    if op == "agg":
        specs.add((cond[1], cond[2]))
        return

    if op in ("and", "or"):
        _collect_aggs(cond[1], specs)
        _collect_aggs(cond[2], specs)
    elif op == "not":
        _collect_aggs(cond[1], specs)
    elif op in _COMPARISON_OPS:
        _collect_operand(cond[1], specs)
        _collect_operand(cond[2], specs)
    elif op == "is_null":
        _collect_operand(cond[1], specs)
    elif op == "in":
        _collect_operand(cond[1], specs)
    elif op == "in_prepared":
        _collect_operand(cond[1], specs)
    elif op == "between":
        _collect_operand(cond[1], specs)


def _prepare_condition(cond):
    if cond is None:
        return None

    op = cond[0]

    if op in ("and", "or"):
        return [op, _prepare_condition(cond[1]), _prepare_condition(cond[2])]

    if op == "not":
        return [op, _prepare_condition(cond[1])]

    if op == "in":
        non_null = set()
        has_null = False
        for v in cond[2]:
            if v is None:
                has_null = True
            else:
                non_null.add(v)
        return ["in_prepared", cond[1], non_null, has_null, len(cond[2]) == 0]

    return cond


def _value_where(opd, row):
    if opd[0] == "col":
        return row[opd[1]]
    return opd[1]


def _compare(op, x, y):
    if x is None or y is None:
        return None

    if op == "=":
        return x == y
    if op == "!=":
        return x != y
    if op == "<":
        return x < y
    if op == "<=":
        return x <= y
    if op == ">":
        return x > y
    return x >= y


def _eval_where(cond, row):
    op = cond[0]

    if op == "and":
        a = _eval_where(cond[1], row)
        if a is False:
            return False
        b = _eval_where(cond[2], row)
        if b is False:
            return False
        if a is None or b is None:
            return None
        return True

    if op == "or":
        a = _eval_where(cond[1], row)
        if a is True:
            return True
        b = _eval_where(cond[2], row)
        if b is True:
            return True
        if a is None or b is None:
            return None
        return False

    if op == "not":
        a = _eval_where(cond[1], row)
        if a is None:
            return None
        return not a

    if op == "is_null":
        return _value_where(cond[1], row) is None

    if op == "in_prepared":
        x = _value_where(cond[1], row)
        if cond[4]:
            return False
        if x is not None and x in cond[2]:
            return True
        if x is None or cond[3]:
            return None
        return False

    if op == "between":
        x = _value_where(cond[1], row)
        a = _compare(">=", x, cond[2])
        if a is False:
            return False
        b = _compare("<=", x, cond[3])
        if b is False:
            return False
        if a is None or b is None:
            return None
        return True

    return _compare(op, _value_where(cond[1], row), _value_where(cond[2], row))


def _value_having(opd, group_values, agg_values):
    tag = opd[0]
    if tag == "col":
        return group_values.get(opd[1])
    if tag == "val":
        return opd[1]
    return agg_values[(opd[1], opd[2])]


def _eval_having(cond, group_values, agg_values):
    op = cond[0]

    if op == "and":
        a = _eval_having(cond[1], group_values, agg_values)
        if a is False:
            return False
        b = _eval_having(cond[2], group_values, agg_values)
        if b is False:
            return False
        if a is None or b is None:
            return None
        return True

    if op == "or":
        a = _eval_having(cond[1], group_values, agg_values)
        if a is True:
            return True
        b = _eval_having(cond[2], group_values, agg_values)
        if b is True:
            return True
        if a is None or b is None:
            return None
        return False

    if op == "not":
        a = _eval_having(cond[1], group_values, agg_values)
        if a is None:
            return None
        return not a

    if op == "is_null":
        return _value_having(cond[1], group_values, agg_values) is None

    if op == "in_prepared":
        x = _value_having(cond[1], group_values, agg_values)
        if cond[4]:
            return False
        if x is not None and x in cond[2]:
            return True
        if x is None or cond[3]:
            return None
        return False

    if op == "between":
        x = _value_having(cond[1], group_values, agg_values)
        a = _compare(">=", x, cond[2])
        if a is False:
            return False
        b = _compare("<=", x, cond[3])
        if b is False:
            return False
        if a is None or b is None:
            return None
        return True

    return _compare(
        op,
        _value_having(cond[1], group_values, agg_values),
        _value_having(cond[2], group_values, agg_values),
    )


def _compute_aggregates(group_rows, agg_specs):
    if group_rows is None:
        group_rows = []

    values = {}

    for func, arg in agg_specs:
        if func == "count":
            if arg == "*":
                values[(func, arg)] = len(group_rows)
            else:
                cnt = 0
                for row in group_rows:
                    if row[arg] is not None:
                        cnt += 1
                values[(func, arg)] = cnt

        elif func == "count_distinct":
            seen = set()
            for row in group_rows:
                v = row[arg]
                if v is not None:
                    seen.add(v)
            values[(func, arg)] = len(seen)

        elif func == "sum":
            total = 0
            has = False
            for row in group_rows:
                v = row[arg]
                if v is not None:
                    total += v
                    has = True
            values[(func, arg)] = total if has else None

        elif func == "min":
            best = None
            has = False
            for row in group_rows:
                v = row[arg]
                if v is not None:
                    if not has or v < best:
                        best = v
                        has = True
            values[(func, arg)] = best if has else None

        elif func == "max":
            best = None
            has = False
            for row in group_rows:
                v = row[arg]
                if v is not None:
                    if not has or v > best:
                        best = v
                        has = True
            values[(func, arg)] = best if has else None

        elif func == "avg":
            total = 0
            cnt = 0
            for row in group_rows:
                v = row[arg]
                if v is not None:
                    total += v
                    cnt += 1
            values[(func, arg)] = total // cnt if cnt else None

    return values


def _apply_order_by(result, order_by):
    for key, direction, nulls in reversed(order_by):
        if nulls is None:
            nulls_first = direction == "asc"
        else:
            nulls_first = nulls == "first"

        desc = direction == "desc"

        null_rows = []
        value_rows = []

        for row in result:
            if row.get(key) is None:
                null_rows.append(row)
            else:
                value_rows.append(row)

        if desc:
            value_rows.sort(key=lambda r, k=key: r[k], reverse=True)
        else:
            value_rows.sort(key=lambda r, k=key: r[k])

        if nulls_first:
            result = null_rows + value_rows
        else:
            result = value_rows + null_rows

    return result


def run_query(rows: list[dict], query: dict) -> list[dict]:
    select = query["select"]
    where = query.get("where")
    group_by = query.get("group_by") or []
    having = query.get("having")
    distinct = query.get("distinct")
    order_by = query.get("order_by")
    offset = query.get("offset")
    limit = query.get("limit")

    select_items = []
    output_keys = []
    agg_specs = set()

    for item in select:
        if isinstance(item, str):
            select_items.append(("col", item, item))
            output_keys.append(item)
        else:
            func = item[0]
            arg = item[1]
            spec = (func, arg)
            key = f"{func}({arg})"
            select_items.append(("agg", spec, key))
            output_keys.append(key)
            agg_specs.add(spec)

    if having is not None:
        _collect_aggs(having, agg_specs)

    grouped = bool(group_by) or bool(agg_specs)

    where_cond = _prepare_condition(where) if where is not None else None
    having_cond = _prepare_condition(having) if having is not None else None

    if not grouped:
        cols = [data for kind, data, _ in select_items]
        if where_cond is None:
            result = [{c: row[c] for c in cols} for row in rows]
        else:
            result = [
                {c: row[c] for c in cols}
                for row in rows
                if _eval_where(where_cond, row) is True
            ]

    else:
        agg_specs_list = list(agg_specs)

        if not group_by:
            if where_cond is None:
                group_rows = rows
            else:
                group_rows = [
                    row for row in rows if _eval_where(where_cond, row) is True
                ]

            agg_values = (
                _compute_aggregates(group_rows, agg_specs_list)
                if agg_specs_list
                else {}
            )

            result = []
            if having_cond is None or _eval_having(having_cond, {}, agg_values) is True:
                out_row = {}
                for kind, data, key in select_items:
                    if kind == "col":
                        out_row[key] = group_rows[0][data] if group_rows else None
                    else:
                        out_row[key] = agg_values[data]
                result.append(out_row)

        else:
            groups = {}

            if where_cond is None:
                if agg_specs_list:
                    for row in rows:
                        key = tuple(row[c] for c in group_by)
                        lst = groups.get(key)
                        if lst is None:
                            groups[key] = [row]
                        else:
                            lst.append(row)
                else:
                    for row in rows:
                        key = tuple(row[c] for c in group_by)
                        if key not in groups:
                            groups[key] = None
            else:
                if agg_specs_list:
                    for row in rows:
                        if _eval_where(where_cond, row) is True:
                            key = tuple(row[c] for c in group_by)
                            lst = groups.get(key)
                            if lst is None:
                                groups[key] = [row]
                            else:
                                lst.append(row)
                else:
                    for row in rows:
                        if _eval_where(where_cond, row) is True:
                            key = tuple(row[c] for c in group_by)
                            if key not in groups:
                                groups[key] = None

            result = []

            for key, group_rows in groups.items():
                group_values = dict(zip(group_by, key))

                agg_values = (
                    _compute_aggregates(group_rows, agg_specs_list)
                    if agg_specs_list
                    else {}
                )

                if having_cond is not None:
                    if _eval_having(having_cond, group_values, agg_values) is not True:
                        continue

                out_row = {}
                for kind, data, out_key in select_items:
                    if kind == "col":
                        out_row[out_key] = group_values.get(data)
                    else:
                        out_row[out_key] = agg_values[data]

                result.append(out_row)

    if distinct:
        seen = set()
        unique_result = []

        if output_keys:
            for row in result:
                marker = tuple(row.get(k) for k in output_keys)
                if marker not in seen:
                    seen.add(marker)
                    unique_result.append(row)
        else:
            if result:
                unique_result.append(result[0])

        result = unique_result

    if order_by:
        result = _apply_order_by(result, order_by)

    start = offset if offset else 0

    if limit is None:
        if start:
            result = result[start:]
    else:
        result = result[start:start + limit]

    return result
